-- Restore all dialogue used by Grizzle, the bosses, and the end sequence.
DELETE FROM `creature_text` WHERE `CreatureID` IN (70788,70792,70824,70956,70959,71123,71177,71246,71358);

DELETE FROM `spell_script_names` WHERE `spell_id` IN (141387,141418,141456,141458,141665,142150) OR `ScriptName` IN ('spell_darkheart_urtharges_shield_eff','spell_darkheart_rupture_line_launcher','spell_darkheart_detonate','spell_darkheart_detonate_eff','spell_darkheart_dark_blood_eff','spell_darkheart_dark_blood');

DELETE FROM `areatrigger_scripts` WHERE `entry` IN (4641,4642,4645,4646,4727) OR `ScriptName` IN ('sat_darkheart_artifact','sat_darkheart_heart_corruption_visual');

ON DUPLICATE KEY UPDATE `parent`=VALUES(`parent`),`script`=VALUES(`script`),`allowMount`=VALUES(`allowMount`),`bonusChance`=VALUES(`bonusChance`);
DELETE FROM `scenario_data` WHERE `MapID`=1144 OR `ScenarioID`=216;

-- Enable only after spawn, scripts, paths, dialogue, and scenario mapping are installed.
DELETE FROM `disables` WHERE `sourceType`=2 AND `entry`=1144;
